let language='vi';try{const saved=localStorage.getItem('nail-language');if(['vi','fr','en'].includes(saved))language=saved;}catch{}
const getLocale=()=>({vi:'vi-VN',fr:'fr-FR',en:'en-GB'}[language]);
const originals=new WeakMap(),placeholders=new WeakMap();
function translateText(text){if(language==='vi')return text;const exact=translations.find(row=>row[0]===text.trim());if(exact)return text.replace(text.trim(),exact[language==='fr'?1:2]);let out=text;for(const row of [...translations].sort((a,b)=>b[0].length-a[0].length))out=out.split(row[0]).join(row[language==='fr'?1:2]);return out;}
function translatePage(){observer.disconnect();document.documentElement.lang=language;document.title='Điệu salon · '+translateText('Chấm công');const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);let node;while(node=walker.nextNode()){if(node.parentElement?.closest('script,style,.staff-name,.avatar,.role,option,#accountName,tbody td:first-child,[data-no-translate]'))continue;const old=originals.get(node);const source=old&&node.nodeValue===old.last?old.source:node.nodeValue;const translated=translateText(source);originals.set(node,{source,last:translated});if(node.nodeValue!==translated)node.nodeValue=translated;}document.querySelectorAll('[data-phone-country] option').forEach(option=>{const old=originals.get(option);const source=old&&option.textContent===old.last?old.source:option.textContent;const last=translateText(source);originals.set(option,{source,last});option.textContent=last;});document.querySelectorAll('[placeholder]').forEach(el=>{const source=placeholders.get(el)||el.getAttribute('placeholder');placeholders.set(el,source);el.setAttribute('placeholder',translateText(source));});document.querySelectorAll('[data-language]').forEach(select=>{select.value=language;select.setAttribute('aria-label',({vi:'Ngôn ngữ',fr:'Langue',en:'Language'})[language]);});observer.observe(document.body,{childList:true,subtree:true,characterData:true});}
let pending=false;const observer=new MutationObserver(()=>{if(!pending){pending=true;queueMicrotask(()=>{pending=false;translatePage();});}});
function setLanguage(value){if(!['vi','fr','en'].includes(value))return;language=value;try{localStorage.setItem('nail-language',value);}catch{}translatePage();if(typeof render==='function')render();if(typeof updateOrderCurrency==='function')updateOrderCurrency();}
document.querySelectorAll('[data-language]').forEach(select=>select.addEventListener('change',()=>setLanguage(select.value)));
translatePage();

